101	
102	    private final TelephoneNormalizer telephoneNormalizer;
103	
104	    private final EmailNormalizer emailNormalizer;
105	
106	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
107	
108	    private final AddressNormalizer addressNormalizer;
109	
110	    private final CustomerCodeGenerator customerCodeGenerator;
111	
112	    private final NamesakeCounter namesakeCounter;
113	
114	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
115	
116	    private final OwnerAuditLogger ownerAuditLogger;
117	
118	    public OwnerRestControllerV1(ClinicService clinicService,
119	                                 OwnerMapper ownerMapper,
120	                                 PetMapper petMapper,
121	                                 VisitMapper visitMapper,
122	                                 OwnerFieldsValidator ownerFieldsValidator,
123	                                 PostcodeValidator postcodeValidator,
124	                                 RegistrationDateValidator registrationDateValidator,
125	                                 HouseholdDuplicateValidator householdDuplicateValidator,
126	                                 IdentityDuplicateValidator identityDuplicateValidator,
127	                                 PossibleDuplicateDetector possibleDuplicateDetector,
128	                                 HouseholdIdGenerator householdIdGenerator,
129	                                 TelephoneNormalizer telephoneNormalizer,
130	                                 EmailNormalizer emailNormalizer,
131	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
132	                                 AddressNormalizer addressNormalizer,
133	                                 CustomerCodeGenerator customerCodeGenerator,
134	                                 NamesakeCounter namesakeCounter,
135	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
136	                                 OwnerAuditLogger ownerAuditLogger) {
137	        this.clinicService = clinicService;
138	        this.ownerMapper = ownerMapper;
139	        this.petMapper = petMapper;
140	        this.visitMapper = visitMapper;
141	        this.ownerFieldsValidator = ownerFieldsValidator;
142	        this.postcodeValidator = postcodeValidator;
143	        this.registrationDateValidator = registrationDateValidator;
144	        this.householdDuplicateValidator = householdDuplicateValidator;
145	        this.identityDuplicateValidator = identityDuplicateValidator;
146	        this.possibleDuplicateDetector = possibleDuplicateDetector;
147	        this.householdIdGenerator = householdIdGenerator;
148	        this.telephoneNormalizer = telephoneNormalizer;
149	        this.emailNormalizer = emailNormalizer;
150	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
151	        this.addressNormalizer = addressNormalizer;
152	        this.customerCodeGenerator = customerCodeGenerator;
153	        this.namesakeCounter = namesakeCounter;
154	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
155	        this.ownerAuditLogger = ownerAuditLogger;
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
161	        Collection<Owner> owners;
162	        if (lastName != null) {
163	            owners = this.clinicService.findOwnerByLastName(lastName);
164	        } else {
165	            owners = this.clinicService.findAllOwners();
166	        }
167	        if (owners.isEmpty()) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
186	        if (ownerFieldsDto != null) {
187	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
188	        }
189	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
190	        if (!missingFields.isEmpty()) {
191	            throw new MissingOwnerFieldsException(missingFields);
192	        }
193	        HttpHeaders headers = new HttpHeaders();
194	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
195	        Collection<Owner> sameLastName =
196	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
197	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
198	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
199	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
200	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
201	        disposableEmailDomainValidator.validate(owner.getEmail());
202	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
203	        rejectIfDuplicateIdentity(owner);
204	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
205	        registrationDateValidator.validate(owner.getRegistrationDate());
206	        if (owner.getRegistrationDate() == null) {
207	            owner.setRegistrationDate(LocalDate.now());
208	        }
209	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
210	        LocalDate registrationDate = owner.getRegistrationDate();
211	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
212	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
213	            throw new DailyOwnerLimitException(registrationDate);
214	        }
215	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
216	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
217	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
218	            throw new CityOwnerLimitException(owner.getCity());
219	        }
220	        owner.setCustomerCode(assignCustomerCode(owner));
221	        this.clinicService.saveOwner(owner);
222	        ownerAuditLogger.ownerCreated(owner);
223	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
224	        headers.setLocation(UriComponentsBuilder.newInstance()
225	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
226	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
227	    }
228	
229	    /**
230	     * Assigns the household attributes of an owner about to be created, without touching any
231	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
232	     * name and postcode, so every owner in the same household shares it automatically regardless of
233	     * creation order. The new owner's household size after this create is recorded: the existing
234	     * members that share its household (same last name and postcode) plus the owner itself.
235	     *
236	     * @return the existing members of the owner's household (empty when it starts a new household)
237	     */
238	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
239	        owner.setHouseholdId(householdIdGenerator.generate(owner));
240	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
241	        owner.setHouseholdSize(members.size() + 1);
242	        return members;
243	    }
244	
245	    /**
246	     * Computes the customer code for an owner about to be created, de-duplicated against the codes
247	     * already assigned to existing owners so that distinct owners always receive distinct codes.
248	     *
249	     * @return the owner's unique customer code
250	     */
251	    private String assignCustomerCode(Owner owner) {
252	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
253	        String baseCode = customerCodeGenerator.generate(
254	            region, owner.getTelephone(), owner.getLastName());
255	        List<String> takenCodes = clinicService.findOwnersByCustomerCodeStartingWith(baseCode)
256	            .stream()
257	            .map(Owner::getCustomerCode)
258	            .toList();
259	        return customerCodeGenerator.deduplicate(baseCode, takenCodes);
260	    }
261	
262	    /**
263	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
264	     * When the owner joins an existing household (same last name and postcode) it is rejected as a
265	     * household duplicate, unless the request declared {@code sharesHousehold}: a declared member is
266	     * created and, being knowingly registered, is not treated as a suspected duplicate. When the
267	     * owner starts a new household the ordinary possible-duplicate detection runs.
268	     *
269	     * @throws HouseholdDuplicateException if the owner joins an existing household without opting in
270	     */
271	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
272	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
273	        if (householdMembers.isEmpty()) {
274	            flagPossibleDuplicate(owner, sameLastName);
275	            return;
276	        }
277	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
278	            throw new HouseholdDuplicateException(owner.getHouseholdId());
279	        }
280	        owner.setPossibleDuplicate(false);
281	        owner.setPossibleDuplicateOf(null);
282	    }
283	
284	    /**
285	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
286	     * owner. A full-key match requires an equal telephone, so only owners with the same
287	     * (already normalized) telephone are compared.
288	     *
289	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
290	     */
291	    private void rejectIfDuplicateIdentity(Owner owner) {
292	        Collection<Owner> sameTelephone = this.clinicService.findOwnersByTelephone(owner.getTelephone());
293	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
294	            throw new DuplicateIdentityException(IdentityKey.of(owner));
295	        }
296	    }
297	
298	    /**
299	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
300	     * existing owner's last name and postcode with a different telephone. The matching owner's id
301	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
302	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
303	     * seen here is guaranteed not to be a hard duplicate.
304	     */
305	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
306	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
307	        owner.setPossibleDuplicate(match != null);
308	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
309	    }
310	
311	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
312	    @Override
313	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
314	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
315	        if (currentOwner == null) {
316	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
317	        }
318	        currentOwner.setAddress(ownerFieldsDto.getAddress());
319	        currentOwner.setCity(ownerFieldsDto.getCity());
320	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
321	        currentOwner.setLastName(ownerFieldsDto.getLastName());
322	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
323	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
324	        this.clinicService.saveOwner(currentOwner);
325	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
326	    }
327	
328	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
329	    @Transactional
330	    @Override
331	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
332	        Owner owner = this.clinicService.findOwnerById(ownerId);
333	        if (owner == null) {
334	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
335	        }
336	        this.clinicService.deleteOwner(owner);
337	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
338	    }
339	
340	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
341	    @Override
342	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
343	        Owner owner = this.clinicService.findOwnerById(ownerId);
344	        if (owner == null) {
345	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
346	        }
347	        HttpHeaders headers = new HttpHeaders();
348	        Pet pet = petMapper.toPet(petFieldsDto);
349	        owner.setId(ownerId);
350	        pet.setOwner(owner);
351	        pet.getType().setName(null);
352	        this.clinicService.savePet(pet);
353	        PetDto petDto = petMapper.toPetDto(pet);
354	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
355	            .buildAndExpand(pet.getId()).toUri());
356	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
357	    }
358	
359	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
360	    @Override
361	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
362	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
363	        if (currentOwner != null) {
364	            Pet currentPet = this.clinicService.findPetById(petId);
365	            if (currentPet != null) {
366	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
367	                currentPet.setName(petFieldsDto.getName());
368	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
369	                this.clinicService.savePet(currentPet);
370	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
371	            }
372	        }
373	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
